const body = $input.first().json.body || $input.first().json;
const data = body.data || body;
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const phone = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '');

if (key.fromMe) return [];

const message = data.message || {};
const messageType = data.messageType || 'unknown';
let textContent = '';
if (messageType === 'conversation') textContent = message.conversation || '';
else if (messageType === 'extendedTextMessage') textContent = (message.extendedTextMessage || {}).text || '';
else if (messageType === 'audioMessage') textContent = '[رسالة صوتية]';
else textContent = message.conversation || message.text || '';

// Normalize days → nights
textContent = textContent.replace(/(\d+)\s*(ايام|أيام|يوم)/g, (m, d) => {
  const nights = parseInt(d, 10) - 1;
  return nights + ' ليالي';
});
textContent = textContent.replace(/اسبوعين|أسبوعين/g, '13 ليالي');
textContent = textContent.replace(/اسبوع|أسبوع/g, '7 ليالي');
textContent = textContent.replace(/عشر ايام|عشرة ايام|عشر أيام|عشرة أيام/g, '9 ليالي');
textContent = textContent.replace(/خمسة ايام|خمس ايام|خمسة أيام/g, '4 ليالي');
textContent = textContent.replace(/ستة ايام|ست ايام/g, '5 ليالي');

const MANAGER_PHONE = '380936582617';
const isManager = phone === MANAGER_PHONE;
const SB = String($env.SUPABASE_URL || 'https://xfibcjhshpmqkrhlpsoa.supabase.co').replace(/\/$/, '') + '/rest/v1';
const KEY = $env.SUPABASE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY;
if (!KEY) throw new Error('SUPABASE_KEY required');
const h = { apikey: KEY, Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' };

function leadHasStoredTrip(lead) {
  if (!lead) return false;
  return !!(lead.destination || lead.travel_dates || lead.pax_adults || lead.pax_children || lead.notes);
}

function buildLeadStateSummary(lead) {
  if (!lead) return '';
  const parts = [];
  if (lead.name) parts.push('الاسم: ' + lead.name);
  if (lead.destination) parts.push('الوجهة: ' + lead.destination);
  if (lead.travel_dates) parts.push('التواريخ: ' + lead.travel_dates);
  if (lead.pax_adults != null) parts.push('الكبار: ' + lead.pax_adults);
  if (lead.pax_children != null) parts.push('الأطفال: ' + lead.pax_children);
  if (lead.children_ages) parts.push('أعمار الأطفال: ' + lead.children_ages);
  if (lead.stage) parts.push('المرحلة: ' + lead.stage);
  if (lead.offer_sent) parts.push('تم إرسال عرض');
  if (lead.objection_type) parts.push('اعتراض سابق: ' + lead.objection_type);
  if (lead.notes) parts.push('ملاحظات: ' + String(lead.notes).slice(0, 300));
  return parts.join(' | ');
}

const trimmed = textContent.trim();
const returningRx = /(خبرتكم|خبرتك|قلت\s*لك|قلت\s*لنا|قلت\s*لهم|سبق\s*و|قبل\s*كذا|قبل\s*قلت|انا\s*خبرت|أنا\s*خبرت|already\s*told|told\s*you)/i;
const newTripRx = /^(جديد|بداية\s*جديدة|new\s*trip|رحلة\s*جديدة|من\s*الاول|من\s*الأول)/i;
const greetingRx = /^(السلام|سلام|مرحبا|هلا|أهلا|ياهلا|صباح|مساء|هلو|hello|hi\b)/i;
const hotelOnlyRx = /(فندق\s*فقط|فنادق\s*بس|بس\s*فندق|فقط\s*فندق|hotel\s*only|بدون\s*جولات|بدون\s*استقبال|هذا\s*فنادق)/i;
const priceObjectionRx = /(غالي|غالية|سعركم|السعر\s*عالي|expensive|too\s*much|ارخص|أرخص)/i;
const goodbyeRx = /(لا\s*خلاص|خلاص\s*شكر|شكر\s*بس|ما\s*بغى|ما\s*ابغى|مو\s*مهتم|not\s*interested|thanks?\s*bye)/i;
const aiQuestionRx = /(انت\s*ذكاء|أنت\s*ذكاء|روبوت|bot|ai\b|ذكاء\s*اصطناع|إنسان|بشر|human)/i;

const isReturningCustomer = returningRx.test(trimmed);
const isExplicitNewTrip = newTripRx.test(trimmed);
const isGreeting = greetingRx.test(trimmed);

let isNew = false;
let lead = null;
try {
  const r = await this.helpers.httpRequest({ method: 'GET', url: `${SB}/leads?phone=eq.${phone}&limit=1`, headers: h });
  if (r.length > 0) {
    lead = r[0];
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${SB}/leads?phone=eq.${phone}`,
      headers: { ...h, Prefer: 'return=minimal' },
      body: { last_contact: new Date().toISOString(), updated_at: new Date().toISOString() },
    });
  } else {
    isNew = true;
    if (!isManager) {
      const r2 = await this.helpers.httpRequest({
        method: 'POST',
        url: `${SB}/leads`,
        headers: { ...h, Prefer: 'return=representation' },
        body: { phone, stage: 'new', assigned_to: 'bot', source: 'direct', last_contact: new Date().toISOString() },
      });
      lead = r2[0] || null;
    }
  }
} catch (e) {}

if (!isManager) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${SB}/conversations`,
      headers: { ...h, Prefer: 'return=minimal' },
      body: { phone, role: 'user', message: textContent },
    });
  } catch (e) {}
}

// Session reset ONLY on explicit new-trip intent — never wipe stored lead on simple greeting or returning customer
const shouldResetLead = isExplicitNewTrip && phone && !isReturningCustomer;
if (shouldResetLead) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: SB + '/leads?phone=eq.' + phone,
      headers: { ...h, Prefer: 'return=minimal' },
      body: {
        stage: 'new',
        destination: null,
        travel_dates: null,
        pax_adults: null,
        pax_children: null,
        children_ages: null,
        offer_sent: false,
        notes: null,
        next_followup: null,
        follow_up_count: 0,
        objection_type: null,
        needs_human: false,
        updated_at: new Date().toISOString(),
      },
    });
    if (lead) {
      lead.stage = 'new';
      lead.destination = null;
      lead.travel_dates = null;
      lead.pax_adults = null;
      lead.pax_children = null;
      lead.children_ages = null;
      lead.offer_sent = false;
      lead.notes = null;
    }
  } catch (e) {}
  try {
    const cutoff = new Date(Date.now() - 30000).toISOString();
    await this.helpers.httpRequest({
      method: 'DELETE',
      url: `${SB}/conversations?phone=eq.${phone}&created_at=lt.${encodeURIComponent(cutoff)}`,
      headers: h,
      returnFullResponse: true,
    });
  } catch (e) {}
}

let chatHistory = '';
try {
  const msgs = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SB}/conversations?phone=eq.${phone}&order=id.asc&limit=30`,
    headers: h,
  });
  chatHistory = msgs.map((m) => (m.role === 'user' ? 'العميل' : 'ليلى') + ': ' + m.message).join('\n');
} catch (e) {}

let managerInstructions = '';
try {
  const inst = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SB}/manager_instructions?active=eq.true&order=created_at.desc&limit=20`,
    headers: h,
  });
  if (inst.length > 0) managerInstructions = inst.map((i) => '- ' + i.instruction).join('\n');
} catch (e) {}

const leadStateSummary = buildLeadStateSummary(lead);
const conversationHints = [];
if (isReturningCustomer) {
  conversationHints.push('العميل يقول إنه سبق وأخبرنا — لا تعيدي سؤال التفاصيل المحفوظة؛ استخدمي leadContext فقط واسألي عن الناقص.');
}
if (leadHasStoredTrip(lead) && !isExplicitNewTrip) {
  conversationHints.push('يوجد بيانات رحلة محفوظة — لا تطلبي وجهة/تواريخ/عدد إذا موجودة؛ أكملي من حيث توقفتم.');
}
if (hotelOnlyRx.test(trimmed)) {
  conversationHints.push('تصحيح نطاق: العميل يريد فندق فقط — أكدي باختصار ثم طبّقي سياسة أركاديا (الحد الأدنى فندق+استقبال، جولات اختيارية).');
}
if (priceObjectionRx.test(trimmed)) {
  conversationHints.push('اعتراض سعر — ردّي باختصار «تمام، خليني أشوف لك خيارات أوفر 👍» ثم list_hotels أو get_package_quote؛ لا خصم مخترع.');
}
if (goodbyeRx.test(trimmed)) {
  conversationHints.push('العميل ينهي المحادثة — ردّ قصير طبيعي مثل «العفو، حياك الله 🌷» بدون فقرة ختامية طويلة.');
}
if (aiQuestionRx.test(trimmed)) {
  conversationHints.push('سؤال عن AI/إنسان — لا تدّعي أنكِ بشرية؛ قولي باختصار أنكِ ليلى مساعدة أركاديا.');
}

let context = '';
if (isManager) context = 'هذا المدير أبو أمير — عامليه كمديرك.';
else if (isNew) context = 'عميل جديد — عرّفي نفسك باختصار «أنا ليلى من أركاديا» فقط إذا يلزم.';
else if (isReturningCustomer || leadHasStoredTrip(lead)) context = 'عميل سابق — لا تعرّفي نفسك ولا تسألي تفاصيل محفوظة.';
else if (isGreeting) context = 'تحية — ردّي باختصار واسألي فقط عن الناقص.';
else context = 'عميل سابق — لا تعرّفي نفسك.';
if (leadStateSummary) context += ' بيانات محفوظة: ' + leadStateSummary + '.';

const enWords = (textContent.match(/[a-zA-Z]{3,}/g) || []).length;
const totalWords = textContent.trim().split(/\s+/).length;
const customerLanguage = enWords / Math.max(totalWords, 1) > 0.5 ? 'en' : 'ar';

return [{
  json: {
    phone,
    remoteJid,
    textContent,
    customerLanguage,
    isManager,
    isNew,
    lead,
    leadStateSummary,
    chatHistory,
    managerInstructions,
    context,
    conversationHints,
  },
}];

const de = $('Decision Engine').first()?.json || {};
const prev = { ...de, ...($input.first().json || {}) };
const SB = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1';
const KEY = 'REDACTED_SUPABASE_SERVICE_ROLE_KEY';
const h = { 'apikey':KEY, 'Authorization':'Bearer '+KEY, 'Content-Type':'application/json', 'Prefer':'return=minimal' };
if (!prev.isManager) {
  try { await this.helpers.httpRequest({ method:'POST', url:`${SB}/conversations`, headers:h, body:{ phone:prev.phone, role:'assistant', message:prev.response } }); } catch(e) {}
}
return [{ json: prev }];

// ========================================
// Cancel Follow-up on Client Reply
// أول Code node في Laila V4 (بعد Webhook)
// يستخدم this.helpers.httpRequest (لا fetch)
// ========================================

const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SUPABASE_KEY = 'REDACTED_SUPABASE_SERVICE_ROLE_KEY';

const raw     = $input.first().json;
const msgData = raw.data || raw;

// Defensive fromMe detection
const incomingPhone = msgData?.key?.remoteJid?.replace('@s.whatsapp.net', '');
const isFromBot     = msgData?.key?.fromMe === true || msgData?.message?.fromMe === true;

if (!incomingPhone || isFromBot) {
  return $input.all();
}

try {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/leads?phone=eq.${incomingPhone}`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation',
    },
    body: {
      next_followup: null,
      last_contact: new Date().toISOString(),
    },
    json: true,
  });
} catch(e) {
  // لا نوقف الـ flow لو الـ patch فشل
  console.log(`[CANCEL-FU] patch failed: ${e.message}`);
}

return $input.all();

// ========================================
// Set Follow-up — Smart Detection
// بعد "Send WhatsApp" في Laila V4
// يستخدم this.helpers.httpRequest (لا fetch)
// ========================================

const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SUPABASE_KEY = 'REDACTED_SUPABASE_SERVICE_ROLE_KEY';

const ctx    = $input.first().json;
const phone  = ctx.phone
  || ctx.data?.key?.remoteJid?.replace('@s.whatsapp.net', '')
  || ctx.from;

const botMsg      = ctx.botMessage || ctx.finalResponse || ctx.message || '';
const destination = ctx.destination || ctx.context?.destination || null;
const name        = ctx.name || ctx.clientName || null;

if (!phone) return $input.all();

// Price Detection
const PRICE_PATTERNS = [
  /\$[\d,]+/, /USD\s*[\d,]+/i,
  /[\d,]{3,}\s*(دولار|ريال|درهم)/,
  /السعر[:\s]+/, /🥇|🥈|🥉/,
  /الاقتصادي|الفاخر|المتوسط/,
  /ليلة.*\$/,
];

const hasPriceSent = PRICE_PATTERNS.some(p => p.test(botMsg));
if (!hasPriceSent) return $input.all();

const nextFollowup = new Date(Date.now() + 30 * 60 * 1000).toISOString();

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/leads`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'resolution=merge-duplicates,return=representation',
    },
    body: {
      phone, name, destination,
      stage: 'quoted',
      follow_up_count: 0,
      next_followup: nextFollowup,
      paused: false,
      source: 'laila_v4',
    },
    json: true,
  });
} catch(e) {
  console.log(`[SET-FU] failed: ${e.message}`);
}

return $input.all();

// Laila WhatsApp → AI agent with lead/conversation context (conversation-behavior patch)
const phone = $json.phone;
const remoteJid = $json.remoteJid;
const text = $json.textContent || $json.text || '';
const isManager = $json.isManager || false;

const payload = {
  action: 'sendMessage',
  sessionId: String(phone || 'wa'),
  chatInput: text,
  leadContext: $json.leadStateSummary || '',
  chatHistory: $json.chatHistory || '',
  managerInstructions: $json.managerInstructions || '',
  context: $json.context || '',
  conversationHints: ($json.conversationHints || []).join('\n'),
  customerLanguage: $json.customerLanguage || 'ar',
};

let response = '';
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://n8n.arcadia-tour.cloud/webhook/cc004272-5e46-4e5c-be6d-ba84fdf35258/chat',
    body: payload,
    json: true,
    timeout: 90000,
  });
  if (typeof res === 'string') {
    try {
      response = JSON.parse(res).output;
    } catch (e) {
      response = res;
    }
  } else {
    response = (res && (res.output || res.text || res.response)) || '';
  }
} catch (e) {
  response = '';
}
if (!response) {
  response =
    'أهلاً 👋 صار خطأ تقني بسيط، جرّب ترسل طلبك مرة ثانية أو تواصل معنا واتساب: https://wa.me/380936582617';
}
const followup = /دولار|\$|💵/.test(response);
return [{ json: { phone, remoteJid, response, isManager, followup } }];

// Phase1 observability — parse Decision Engine response (no pricing logic change)
const de = $input.first().json;
const ctx = $('Arcadia - Phase1 Inbound Pipeline').first()?.json || {};
const response = String(de.response || '');
const priceUsd = response.match(/\$[\d,]+/)?.[0] || response.match(/([\d,]{3,})\s*USD/i)?.[0] || null;
const manualPath = /no_hotel|يدوي|human|موظف|فريق/i.test(response);
const hasPrice = !!priceUsd || /\$[\d,]{2,}|USD\s*[\d,]+|دولار/.test(response);
return [{ json: {
  phone: de.phone,
  remoteJid: de.remoteJid,
  response: de.response,
  isManager: de.isManager,
  followup: de.followup,
  lead_id: ctx.lead_id,
  customer_id: ctx.customer_id,
  channel: ctx.phase1?.channel || 'whatsapp',
  action_type: 'get_price',
  status: manualPath && !hasPrice ? 'failed' : (hasPrice ? 'success' : 'failed'),
  output_summary: (priceUsd || response).slice(0, 500),
  input_summary: String(ctx.phase1?.message_text || '').slice(0, 500),
  metadata: { phase1: 'pricing_observability', source: 'decision_engine_response' }
}}];

// Phase1 — normalize inbound (no prompt / stage changes)
const j = $input.first().json;
const raw = $('WhatsApp Webhook').first()?.json || $('Telegram Trigger').first()?.json || {};
const body = raw.body || raw;
const data = body.data || body;
const key = data.key || {};
const waMsg = body.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
const tgMsg = raw.message || body.message;
const msg = waMsg || tgMsg || body.messages?.[0] || {};
const phone = String(
  j.phone
  || key.remoteJid?.replace('@s.whatsapp.net', '').replace('@g.us', '')
  || msg.from
  || tgMsg?.chat?.id
  || body.from?.id
  || j.chat_id
  || ''
).trim();
const providerMessageId = key.id ? String(key.id)
  : (waMsg?.id ? String(waMsg.id)
  : (tgMsg?.message_id != null ? String(tgMsg.message_id) : (j.provider_message_id || null)));
const channel = key.remoteJid || waMsg?.id ? 'whatsapp' : (tgMsg ? 'telegram' : (j.channel || 'whatsapp'));
const text = j.textContent || j.text || msg.text?.body || msg.body || tgMsg?.text || '';
const ALLOWED = new Set(['text','image','audio','document','location','video','sticker','unknown']);
const TYPE_MAP = { conversation: 'text', extendedTextMessage: 'text', audioMessage: 'audio', imageMessage: 'image', documentMessage: 'document', videoMessage: 'video', stickerMessage: 'sticker' };
const rawType = data.messageType || msg.type || (tgMsg?.photo ? 'image' : 'text');
const messageType = TYPE_MAP[rawType] || (ALLOWED.has(rawType) ? rawType : 'unknown');
return [{ json: {
  ...j,
  phase1: {
    phone,
    provider_message_id: providerMessageId,
    channel,
    message_text: text,
    message_type: messageType,
    metadata: { raw_channel: channel, normalized_at: new Date().toISOString(), source: 'phase1_normalize' }
  }
}}];

// Phase1 — prepare outbound log AFTER successful send only
function extractOutboundText(val) {
  if (val == null) return null;
  if (typeof val === 'string') { const s = val.trim(); return s || null; }
  if (typeof val === 'object') {
    return val.conversation || val.extendedTextMessage?.text || val.text || null;
  }
  return null;
}
const send = $input.first().json;
const de = $('Decision Engine').first()?.json || {};
const ctx = $('Arcadia - Phase1 Inbound Pipeline').first()?.json
  || $('Phase1 IF Proceed (not duplicate)').first()?.json
  || {};
const messageText = extractOutboundText(send.text)
  || extractOutboundText(send.message)
  || extractOutboundText(send.body?.text)
  || extractOutboundText(send.body)
  || (typeof send.output === 'string' ? send.output.trim() : null)
  || (typeof send.reply === 'string' ? send.reply.trim() : null)
  || (typeof de.response === 'string' ? de.response.trim() : null);
return [{ json: {
  lead_id: ctx.lead_id,
  customer_id: ctx.customer_id,
  conversation_id: ctx.conversation_id,
  channel: ctx.phase1?.channel || ctx.channel,
  message_text: messageText,
  provider_message_id: send.message_id || send.messages?.[0]?.id || send.key?.id || null,
  metadata: { phase1: 'outbound_after_send_success' }
}}];
